                    ),
                    Text('Admin control centre'),
                  ],
                ),
              ),
              ListTile(
                leading: const Icon(Icons.dashboard_outlined),
                title: const Text('Dashboard'),
                selected: true,
                onTap: () => Navigator.of(context).pop(),
              ),
              for (final group in adminGroups.entries) ...[
                Padding(
                  padding: const EdgeInsets.fromLTRB(24, 20, 24, 8),
                  child: Text(
                    group.key.toUpperCase(),
                    style: Theme.of(context).textTheme.labelSmall,
                  ),
                ),
                for (final item in group.value)
                  ListTile(
                    leading: Icon(item.$2),
                    title: Text(item.$1),
                    onTap: () {
                      Navigator.of(context).pop();
                      context.push(
                        item.$3 == 'stats'
                            ? '/admin/stats'
                            : '/admin/${item.$3}',
                      );
                    },
                  ),
              ],
              const Divider(),
              ListTile(
                leading: const Icon(Icons.phone_android_rounded),
                title: const Text('Student view'),
                onTap: () {
                  Navigator.of(context).pop();
                  context.go('/home');
                },
              ),
              ListTile(
                leading: const Icon(Icons.logout_rounded),
                title: const Text('Log out'),
                onTap: () {
                  Navigator.of(context).pop();
                  logout(context, ref);
                },
              ),
            ],
          ),
        ),
      ),
      subtitle: 'PHARM D WITH HYZEN · Admin console',
      actions: [
        IconButton(
          tooltip: 'Student view',
          onPressed: () => context.go('/home'),
          icon: const Icon(Icons.phone_android_rounded),
        ),
      ],
      onRefresh: sync,
      slivers: [
        SliverPadding(
          padding: const EdgeInsets.symmetric(horizontal: 20),
          sliver: SliverList.list(
            children: [
              HeroPanel(
                eyebrow: 'Your control centre',
                title: 'Admin dashboard',
                subtitle: 'Manage content and orders',
                icon: Icons.admin_panel_settings_rounded,
                stats: [
                  ('${orders.length}', 'orders'),
                  (
                    '${messages.where((m) => m['read'] != true).length}',
                    'unread messages',
                  ),
                ],
              ),
              const Gap(16),
              HButton(
                label: 'Refresh website inbox',
                icon: Icons.sync_rounded,
                loading: busy,
                onPressed: sync,
              ),
              for (final group in adminGroups.entries) ...[
                Padding(
                  padding: const EdgeInsets.only(top: 26, bottom: 12),
                  child: Text(
                    group.key.toUpperCase(),
                    style: Theme.of(context).textTheme.labelSmall?.copyWith(
                      letterSpacing: 1.5,
                      color: Theme.of(context).colorScheme.primary,
                    ),
                  ),
                ),
                LayoutBuilder(builder:(context,constraints) => GridView(
                  gridDelegate:SliverGridDelegateWithFixedCrossAxisCount(
                  crossAxisCount:constraints.maxWidth < 560 || MediaQuery.textScalerOf(context).scale(1)>1.4 ? 1 : 2,
                  mainAxisSpacing:8,crossAxisSpacing:10,
                  mainAxisExtent:112 * MediaQuery.textScalerOf(context).scale(1).clamp(1,1.8),
                  ),
                  padding:EdgeInsets.zero, shrinkWrap:true, primary:false,
                  physics:const NeverScrollableScrollPhysics(),
