/// Shared scaffold for auth forms: persistent top bar with Back, keyboard-safe scroll.
class AuthScaffold extends StatelessWidget {
  const AuthScaffold({
    super.key,
    required this.title,
    required this.child,
    this.subtitle,
    this.onBack,
  });
