                        onPressed: _photoBusy
                            ? null
                            : () async {
                                setState(() => _photoBusy = true);
                                try {
                                  final url = await MediaUpload.pickAndUpload();
                                  if (url != null && mounted) {
                                    setState(() => _photo = url);
                                  }
                                } catch (_) {
                                  if (context.mounted) {
                                    showHSnack(
                                      context,
