import 'package:flutter/material.dart';
import '../academics/data/drive_gateway.dart';
import '../../core/errors/app_error.dart';
import 'offline_pdf.dart';
import '../downloads/data/file_store.dart';
import '../academics/domain/drive.dart';

/// PDFium reads byte ranges. Offline save is a separate explicit operation.
class NativePreview extends StatefulWidget {
  const NativePreview({super.key, required this.url});
  final String url;
  @override
  State<NativePreview> createState() => _NativePreviewState();
}
class _NativePreviewState extends State<NativePreview> {
  late Future<DocumentRequest> _request;
  Future<DownloadedFile>? _documentDownload;
  @override
  void initState() { super.initState(); _request = DriveGateway.instance.resolve(widget.url); }
  void _retry() => setState(() => _request = DriveGateway.instance.resolve(widget.url, refresh: true));
  @override
  Widget build(BuildContext context) => FutureBuilder<DocumentRequest>(
    future: _request,
    builder: (context, snapshot) {
      if (snapshot.hasError) {
        final error = snapshot.error;
        return Center(child: Padding(padding: const EdgeInsets.all(24), child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            const Icon(Icons.cloud_off_rounded, size: 40),
            const SizedBox(height: 14),
            Text(error is FriendlyException ? error.message : 'Could not open this file.', textAlign: TextAlign.center),
            const SizedBox(height: 12),
            Wrap(spacing: 8, children: [
              FilledButton(onPressed: _retry, child: const Text('Retry')),
              OutlinedButton(onPressed: () async {
                try { await DriveGateway.instance.connect(); _retry(); }
                catch (e) { if(context.mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('$e'))); }
              }, child: const Text('Connect Google Drive')),
            ]),
          ],
        )));
      }
      final data = snapshot.data;
      if (data == null) return const Center(child: CircularProgressIndicator());
      if (data.mimeType != null && data.mimeType != 'application/pdf') {
        return FutureBuilder<DownloadedFile>(
          future: _documentDownload ??= FileStore.create().download(widget.url, 'preview_${DriveLinks.offlineKey(widget.url)}', (_,__) {}),
          builder:(context,file) => file.hasData ? OfflinePdf(path:file.data!.path) : file.hasError
            ? const Center(child:Text('Could not open this document. Please retry.'))
            : const Center(child:CircularProgressIndicator()),
        );
      }
      return OfflinePdf(uri: data.uri, headers: data.headers);
    },
  );
}

