/// Document viewer. Native chrome, Back top-left, NO "Open original".
class ViewerScreen extends ConsumerStatefulWidget {
  const ViewerScreen({super.key, required this.file});
  final FileRef? file;
  @override
  ConsumerState<ViewerScreen> createState() => _ViewerScreenState();
}

class _ViewerScreenState extends ConsumerState<ViewerScreen> {
  bool _preferOnline = false;

  @override
  void initState() {
    super.initState();
    final f = widget.file;
    if (f != null) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) return;
        ref.read(recentProvider.notifier).touch(f);
      });
    }
  }

  Future<void> _save(FileRef f) async {
    try {
      await ref
          .read(downloadsProvider.notifier)
          .save(f);
      if (mounted) {
        showHSnack(context, 'Saved offline \u2014 find it in Downloads');
      }
    } on FriendlyException catch (e) {
      if (mounted) showHSnack(context, e.message, error: true);
    } catch (_) {
      if (mounted) {
        showHSnack(
          context,
          'Could not save this file. Please retry.',
          error: true,
        );
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    final f = widget.file;
    if (f == null) {
      return Scaffold(
        appBar: const HTopBar(title: 'Document'),
        body: EmptyState(
          icon: Icons.description_outlined,
          title: 'Nothing to show',
          action: HButton(
            label: 'Go home',
            onPressed: () => context.go('/home'),
          ),
        ),
      );
    }
    final rec = ref.watch(downloadForUrlProvider(f.url));
    final ready = rec?.isReady == true && !kIsWeb;
    final showOffline = ready && !_preferOnline;
    final t = Theme.of(context);
    return Scaffold(
      floatingActionButton: const Padding(padding: EdgeInsets.only(bottom:120), child: SectionsButton()),
      appBar: HTopBar(
        title: f.title,
        subtitle: f.trail.isEmpty ? null : f.trail.take(3).join(' \u203a '),
        actions: [
          IconButton(
            tooltip: 'Open in browser',
            icon: const Icon(Icons.open_in_new_rounded),
            onPressed: () => openLink(context, f.url),
          ),
          if (ready)
            IconButton(
              tooltip: 'Export saved file to device',
              icon: const Icon(Icons.save_alt_rounded),
              onPressed: () async {
                try {
                  final path = rec!.localPath!;
                  final ext = path.split('.').last;
                  final exportExt = ext == 'office' || ext == 'legacy'
                      ? (f.title.contains('.')
                            ? f.title.split('.').last
                            : 'bin')
                      : ext;
                  await MediaUpload.exportDocument(
                    path,
                    '${f.title.replaceFirst(RegExp(r"\.[^.]+$"), "").replaceAll(RegExp(r"[^a-zA-Z0-9 _-]"), "")}.$exportExt',
                    ext == 'pdf'
                        ? 'application/pdf'
                        : {
                                'jpg': 'image/jpeg',
                                'png': 'image/png',
                                'webp': 'image/webp',
                              }[ext] ??
                              'application/octet-stream',
                  );
                } catch (_) {
                  if (context.mounted) {
                    showHSnack(context, 'Could not export PDF.', error: true);
                  }
                }
              },
            ),
          if (ready)
            IconButton(
              tooltip: showOffline
                  ? 'Show online preview'
                  : 'Open offline copy',
              icon: Icon(
                showOffline ? Icons.cloud_outlined : Icons.offline_pin_rounded,
              ),
              onPressed: () => setState(() => _preferOnline = !_preferOnline),
            ),
        ],
      ),
      body: Column(
        children: [
          Expanded(
            child: showOffline
                ? OfflinePdf(path: rec!.localPath!)
                : NativePreview(key: ValueKey(f.url), url: f.url),
          ),
          if (!kIsWeb)
            SafeArea(
              top: false,
              child: SurfacePanel(
                radius: 0,
                padding: const EdgeInsets.fromLTRB(
                  HSpace.md,
                  HSpace.sm,
                  HSpace.md,
                  HSpace.sm,
                ),
                child: _OfflineBar(
                  rec: rec,
                  onSave: () => _save(f),
                  onOpen: () => setState(() => _preferOnline = false),
                  onCancel: () => ref
                      .read(downloadsProvider.notifier)
                      .cancel(DriveLinks.offlineKey(f.url)),
                  theme: t,
                ),
              ),
            ),
        ],
      ),
    );
  }
}

class _OfflineBar extends StatelessWidget {
  const _OfflineBar({
    required this.rec,
    required this.onSave,
    required this.onOpen,
    required this.onCancel,
    required this.theme,
  });
  final DownloadRecord? rec;
  final VoidCallback onSave, onOpen, onCancel;
  final ThemeData theme;
  @override
  Widget build(BuildContext context) {
    final r = rec;
    if (r != null && r.status == DownloadStatus.downloading) {
      final p = r.progress;
      return Row(
        children: [
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(
                  p > 0
                      ? 'Downloading ${(p * 100).round()}%'
                      : 'Downloading\u2026 ${formatBytes(r.sizeBytes)}',
                  style: theme.textTheme.titleSmall,
                ),
                Text(r.transferDetail, style: theme.textTheme.bodySmall),
                const SizedBox(height: 6),
                ClipRRect(
                  borderRadius: BorderRadius.circular(8),
                  child: LinearProgressIndicator(
                    value: p > 0 ? p : null,
                    minHeight: 6,
                  ),
                ),
              ],
            ),
          ),
          const SizedBox(width: HSpace.sm),
          TextButton(onPressed: onCancel, child: const Text('Pause')),
        ],
      );
    }
    if (r != null && r.isReady) {
      return Wrap(
        spacing: 8,
        runSpacing: 8,
        crossAxisAlignment: WrapCrossAlignment.center,
        children: [
          const StatusPill(
            label: 'Saved offline',
            color: HColors.success,
            icon: Icons.download_done_rounded,
          ),
          const SizedBox(width: 8),
          Text(formatBytes(r.sizeBytes), style: theme.textTheme.bodySmall),
          FilledButton.icon(
            onPressed: onOpen,
            icon: const Icon(Icons.menu_book_rounded),
            label: const Text('Open offline'),
          ),
        ],
      );
    }
    if (r != null && (r.status == DownloadStatus.failed || r.status == DownloadStatus.paused)) {
      return Row(
        children: [
          const Icon(Icons.error_outline_rounded, color: HColors.error),
          const SizedBox(width: 8),
          Expanded(
            child: Text(
              r.error ?? 'Download failed',
              maxLines: 2,
              overflow: TextOverflow.ellipsis,
              style: theme.textTheme.bodySmall,
            ),
          ),
          const SizedBox(width: 8),
          FilledButton.icon(
            onPressed: onSave,
            icon: const Icon(Icons.refresh_rounded),
            label: Text(r.status == DownloadStatus.paused ? 'Resume' : 'Retry'),
          ),
        ],
      );
    }
    return Row(
      children: [
        Icon(Icons.cloud_download_outlined, color: theme.colorScheme.primary),
        const SizedBox(width: 10),
        Expanded(
          child: Text(
            'Offline copy',
            maxLines: 2,
            overflow: TextOverflow.ellipsis,
            style: theme.textTheme.bodySmall,
          ),
        ),
        const SizedBox(width: 8),
        FilledButton.icon(
          onPressed: onSave,
          style: FilledButton.styleFrom(
            minimumSize: const Size(0, 48),
            padding: const EdgeInsets.symmetric(horizontal: 12),
          ),
          icon: const Icon(Icons.download_rounded, size: 18),
          label: const Text('Save offline'),
        ),
      ],
    );
  }
}

test/download_lifecycle_test.dart:
import 'dart:async';
import 'dart:io';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:hive_flutter/hive_flutter.dart';
import 'package:hyzen_pharmd/core/storage/local_store.dart';
import 'package:hyzen_pharmd/features/academics/domain/models.dart';
import 'package:hyzen_pharmd/features/downloads/data/downloads_controller.dart';
import 'package:hyzen_pharmd/features/downloads/data/file_store.dart';
import 'package:hyzen_pharmd/features/downloads/domain/download_record.dart';

class TestStore implements FileStore {
  @override
  Future<void> discardPartial(String key) async {}
  final transfer = Completer<DownloadedFile>();
  final started = Completer<void>();
  int calls = 0;
  final deleted = <String>[];
  bool cleared = false;
  @override
  bool get supported => true;
  @override
  Future<DownloadedFile> download(
    String url,
    String key,
    ProgressCb progress, {
    bool Function()? cancelled,
  }) {
    calls++;
    if (!started.isCompleted) started.complete();
    return transfer.future;
  }

  @override
  Future<DownloadedFile> importPreview(String path, String key) =>
      Future.value(DownloadedFile(path, 0));

  @override
  Future<bool> exists(String path) async => true;
  @override
  Future<void> delete(String path) async {
    deleted.add(path);
  }

  @override
  Future<void> clearAll() async {
    cleared = true;
  }
}

void main() {
  late Directory temp;
  setUp(() async {
    temp = await Directory.systemTemp.createTemp('hyzen-download-test-');
    Hive.init(temp.path);
    await Hive.openBox<String>(Boxes.downloads);
  });
  tearDown(() async {
    await Hive.close();
    await temp.delete(recursive: true);
  });
  const file = FileRef(
    kind: LibraryKind.notes,
    title: 'Notes',
    url: 'https://example.org/a.pdf',
  );
  test('simultaneous saves share one transfer', () async {
    final store = TestStore();
    final container = ProviderContainer(
      overrides: [fileStoreProvider.overrideWithValue(store)],
    );
    addTearDown(container.dispose);
    final ctrl = container.read(downloadsProvider.notifier);
    final first = ctrl.save(file), second = ctrl.save(file);
    expect(identical(first, second), isTrue);
    await store.started.future;
    expect(store.calls, 1);
    store.transfer.complete(const DownloadedFile('/private/a.pdf', 50));
    await first;
    expect(container.read(downloadsProvider).values.single.isReady, isTrue);
  });
  test('delete during transfer cannot recreate metadata or file', () async {
    final store = TestStore();
    final container = ProviderContainer(
      overrides: [fileStoreProvider.overrideWithValue(store)],
    );
    addTearDown(container.dispose);
    final ctrl = container.read(downloadsProvider.notifier);
    final transfer = ctrl.save(file);
    final failure = expectLater(transfer, throwsException);
    await store.started.future;
    final key = container.read(downloadsProvider).keys.single;
    final removing = ctrl.remove(key);
    store.transfer.complete(const DownloadedFile('/private/a.pdf', 50));
    await removing;
    await failure;
    expect(store.deleted, contains('/private/a.pdf'));
    expect(container.read(downloadsProvider), isEmpty);
    expect(JsonBox(Boxes.downloads).values(), isEmpty);
  });
  test('clear all settles active transfers before clearing storage', () async {
    final store = TestStore();
    final container = ProviderContainer(
      overrides: [fileStoreProvider.overrideWithValue(store)],
    );
    addTearDown(container.dispose);
    final ctrl = container.read(downloadsProvider.notifier);
    final transfer = ctrl.save(file);
    final failure = expectLater(transfer, throwsException);
    await store.started.future;
    final clearing = ctrl.removeAll();
    store.transfer.complete(const DownloadedFile('/private/a.pdf', 50));
    await clearing;
    await failure;
    expect(store.cleared, isTrue);
    expect(container.read(downloadsProvider), isEmpty);
  });
}

test/new_release_test.dart:
import 'dart:io';
import 'dart:convert';
import 'dart:typed_data';
import 'package:flutter_test/flutter_test.dart';
import 'package:http/http.dart' as http;
import 'package:http/testing.dart';
import 'package:archive/archive.dart';
import 'package:hyzen_pharmd/features/downloads/data/file_store_io.dart';
import 'package:hyzen_pharmd/features/downloads/domain/document_type.dart';
import 'package:hyzen_pharmd/features/viewer/office_document.dart';
import 'package:hyzen_pharmd/features/updates/update_manifest.dart';
import 'package:hyzen_pharmd/features/academics/domain/drive.dart';

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();
  test('Drive Office notes use PDF export and retain resource keys', () {
    final url = DriveLinks.downloadUrl(
      'https://drive.google.com/file/d/test-file/view?resourcekey=abc',
      title: 'HLB system.pptx',
    );
    expect(
      url,
      contains('docs.google.com/presentation/d/test-file/export/pdf'),
    );
    expect(Uri.parse(url).queryParameters['resourcekey'], 'abc');
    expect(DriveLinks.offlineKey(url), 'drive_test-file');
  });
  test('types are selected from bytes, HTML is never a document', () {
    expect(documentExtension(utf8.encode('%PDF-1.7\n')), 'pdf');
    expect(documentExtension([137, 80, 78, 71, 13, 10, 26, 10]), 'png');
    expect(documentExtension([255, 216, 255, 0]), 'jpg');
    expect(documentExtension(utf8.encode('<html>Sign in</html>')), isNull);
  });
  test('Office text reader handles slide number order and Word paragraphs', () {
    final a = Archive();
    for (final i in [10, 2, 1]) {
      final xml = utf8.encode('<root><p><t>Slide $i</t></p></root>');
      a.addFile(ArchiveFile('ppt/slides/slide$i.xml', xml.length, xml));
    }
    expect(officePages(Uint8List.fromList(ZipEncoder().encode(a)!)), [
      'Slide 1',
      'Slide 2',
      'Slide 10',
    ]);
    final b = Archive();
    final xml = utf8.encode('<root><p><t>Diabetes notes</t></p></root>');
    b.addFile(ArchiveFile('word/document.xml', xml.length, xml));
    expect(officePages(Uint8List.fromList(ZipEncoder().encode(b)!)), [
      'Diabetes notes',
    ]);
  });
  test(
    'update config rejects missing hash, HTTP, credentials, impossible version',
    () {
      final m = <String, dynamic>{
        'androidLatestVersionCode': 4,
        'androidVersionName': '1.2.1',
        'androidApkUrl': 'https://example.com/app.apk',
        'androidSha256': 'a' * 64,
        'androidMinVersionCode': 3,
      };
      expect(UpdateManifest.parse(m)!.requiredFor(2), isTrue);
      expect(UpdateManifest.parse(m)!.requiredFor(3), isFalse);
      expect(
        UpdateManifest.parse({...m, 'androidLatestVersionCode': 4.0})!.code,
        4,
      );
      for (final bad in [
        <String, dynamic>{'androidSha256': 'wrong'},
        <String, dynamic>{'androidApkUrl': 'http://example.com/a.apk'},
        <String, dynamic>{
          'androidApkUrl': 'https://user:pass@example.com/a.apk',
        },
        <String, dynamic>{'androidMinVersionCode': 5},
      ]) {
        expect(UpdateManifest.parse({...m, ...bad}), isNull);
      }
    },
  );
  test(
    'PDF download finalized and reopens from disk after client is gone',
    () async {
      final dir = await Directory.systemTemp.createTemp('hyzen-test-');
      try {
        final store = createFileStore(
          testDirectory: dir,
          clientFactory: () => MockClient(
            (r) async => http.Response(
              '%PDF-1.7\nfixture\n%%EOF',
              200,
              headers: {'content-type': 'application/pdf'},
            ),
          ),
        );
        final result = await store.download(
          'https://example.com/file',
          'id',
          (r, t) {},
        );
        expect(await File(result.path).readAsString(), startsWith('%PDF-'));
        expect(result.path, endsWith('.pdf'));
        expect(await store.exists(result.path), isTrue);
        expect(
          dir
              .listSync(recursive: true)
              .whereType<File>()
              .where((f) => f.path.endsWith('.part')),
          isEmpty,
        );
        await store.delete(result.path);
        expect(await store.exists(result.path), isFalse);
      } finally {
        await dir.delete(recursive: true);
      }
    },
  );
  test(
    'JPG saves with image renderer extension rather than forced PDF',
    () async {
      final dir = await Directory.systemTemp.createTemp('hyzen-test-');
      try {
        final store = createFileStore(
          testDirectory: dir,
          clientFactory: () => MockClient(
            (r) async =>
                http.Response.bytes([255, 216, 255, 0, 0, 0, 0, 0, 0], 200),
          ),
        );
        expect(
          (await store.download(
            'https://example.com/x',
            'image',
            (r, t) {},
          )).path,
          endsWith('.jpg'),
        );
      } finally {
        await dir.delete(recursive: true);
      }
    },
  );
  test(
    'HTML, unsupported bytes and cancellation never leave ready files',
    () async {
      final dir = await Directory.systemTemp.createTemp('hyzen-test-');
      try {
        for (final body in ['<html>Login</html>', 'not-a-file']) {
          final store = createFileStore(
            testDirectory: dir,
            clientFactory: () =>
                MockClient((r) async => http.Response(body, 200)),
          );
          await expectLater(
            store.download('https://example.com/x', 'bad', (r, t) {}),
            throwsA(anything),
          );
        }
        final store = createFileStore(
          testDirectory: dir,
          clientFactory: () =>
              MockClient((r) async => http.Response('%PDF-1.7', 200)),
        );
        await expectLater(
          store.download(
            'https://example.com/x',
            'cancel',
            (r, t) {},
            cancelled: () => true,
          ),
          throwsA(anything),
        );
        expect(dir.listSync(recursive: true).whereType<File>(), isEmpty);
      } finally {
        await dir.delete(recursive: true);
      }
    },
  );
}

