import 'dart:async';
import 'dart:convert';
import 'dart:io';
import 'package:flutter_test/flutter_test.dart';
import 'package:http/http.dart' as http;
import 'package:hyzen_pharmd/features/academics/data/drive_gateway.dart';
import 'package:hyzen_pharmd/features/downloads/data/file_store_io.dart';
import 'package:hyzen_pharmd/core/utils/validators.dart';

class ScriptClient extends http.BaseClient {
  ScriptClient(this.handler);
  final Future<http.StreamedResponse> Function(http.BaseRequest) handler;
  @override
  Future<http.StreamedResponse> send(http.BaseRequest request)=>handler(request);
}
void main(){
  TestWidgetsFlutterBinding.ensureInitialized();
  test('legacy IDs resolve to Drive v3 media without changing source',(){
    for(final url in ['https://drive.google.com/file/d/abc/view','https://drive.google.com/open?id=abc','https://drive.usercontent.google.com/download?id=abc']){
      final uri=DriveGateway.endpoint(url);
      expect(uri.path,'/drive/v3/files/abc'); expect(uri.queryParameters['alt'],'media');
      expect(uri.toString(),isNot(contains('/preview')));
    }
    expect(DriveGateway.endpoint('https://docs.google.com/document/d/abc/edit').path,endsWith('/export'));
  });
  test('phone error can recover with the supplied corrected number',(){
    expect(Validators.phone('306692796'),isNotNull);
    expect(Validators.phone('03066973691'),isNull);
    expect(PkPhone.normalize('۰۳۰۶۶۹۷۳۶۹۱'),'+923066973691');
    expect(PkPhone.normalize('+92 306 6973691'),'+923066973691');
  });
  test('interrupted downloads resume from validated offset and ETag',()async{
    final dir=await Directory.systemTemp.createTemp('hyzen-range-');
    addTearDown(()=>dir.delete(recursive:true));
    final all=utf8.encode('%PDF-1.7\nfixture data for range test\n%%EOF');
    var calls=0;
    final store=createFileStore(testDirectory:dir,clientFactory:()=>ScriptClient((request)async{
      calls++;
      if(calls==1){
        final stream=Stream<List<int>>.multi((c){c.add(all.sublist(0,18));c.addError(const SocketException('lost'));c.close();});
        return http.StreamedResponse(stream,200,contentLength:all.length,headers:{'etag':'"v1"'});
      }
      expect(request.headers['Range'],'bytes=18-');expect(request.headers['If-Range'],'"v1"');
      return http.StreamedResponse(Stream.value(all.sublist(18)),206,contentLength:all.length-18,
        headers:{'etag':'"v1"','content-range':'bytes 18-${all.length-1}/${all.length}'});
    }));
    await expectLater(store.download('https://example.org/n.pdf','resume',(r,t){}),throwsException);
    final saved=await store.download('https://example.org/n.pdf','resume',(r,t){});
    expect(await File(saved.path).readAsBytes(),all);
    expect(calls,2);
  });
  test('HTML and truncated PDF never become offline files',()async{
    final dir=await Directory.systemTemp.createTemp('hyzen-invalid-');addTearDown(()=>dir.delete(recursive:true));
    for(final bytes in ['<html>Login needed</html>','%PDF-1.7 missing end marker']){
      final store=createFileStore(testDirectory:dir,clientFactory:()=>ScriptClient((_)async=>http.StreamedResponse(Stream.value(utf8.encode(bytes)),200,contentLength:bytes.length)));
      await expectLater(store.download('https://example.org/n.pdf','bad',(r,t){}),throwsException);
    }
    expect(dir.listSync(recursive:true).whereType<File>(),isEmpty);
  });
}

